mapper.select:
select count(distinct problem_id)
from submit_log
where user_id = #{userId}

select se.solution_id as solution_id, se.title, se.problem_id as problem_id, p.title as problem_title, se.`private` as private_, se.create_time as create_time from solution_explanation se inner join problem p on p.problem_id = se.problem_id and p.del_flag = 0 where se.user_id = #{userId}
and se.`private` = 0
order by se.top_up desc, se.create_time desc, se.solution_id desc limit #{limit}
